import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type ConfirmPaymentRequest = {
  /** The balance account ID of the account where the funds should be subtracted. */
  balanceAccountId: string;
  /**
   * The payment token is an identifier for the payment. It is generated by Adyen on the response of
   * the payment details.
   */
  token: string;
};

export const confirmPaymentRequestSchema: Schema<ConfirmPaymentRequest> = s.object<ConfirmPaymentRequest>({
  balanceAccountId: s.string(),
  token: s.string(),
});
